28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
63	    private Set<Pet> pets;
64	
65	    public String getAddress() {
66	        return this.address;
67	    }
68	
69	    public void setAddress(String address) {
70	        this.address = address;
71	    }
72	
73	    public String getCity() {
74	        return this.city;
75	    }
76	
77	    public void setCity(String city) {
78	        this.city = city;
79	    }
80	
81	    public String getTelephone() {
82	        return this.telephone;
83	    }
84	
85	    public void setTelephone(String telephone) {
86	        this.telephone = telephone;
87	    }
88	
89	    public String getEmail() {
90	        return this.email;
91	    }
92	
93	    public void setEmail(String email) {
94	        this.email = normalizeEmail(email);
95	    }
96	
97	    public LocalDate getRegistrationDate() {
98	        return this.registrationDate;
99	    }
100	
101	    public void setRegistrationDate(LocalDate registrationDate) {
102	        this.registrationDate = registrationDate;
103	    }
104	
105	    public String getCustomerCode() {
106	        return this.customerCode;
107	    }
108	
109	    public void setCustomerCode(String customerCode) {
110	        this.customerCode = customerCode;
111	    }
112	
113	    /**
114	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
115	     * source of truth for how an email is persisted, so inputs that differ only in letter case
116	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
117	     * (create and update, mapper or hand-copied) stores the same canonical value.
118	     *
119	     * @param email the raw email, possibly {@code null}
120	     * @return the lower-cased form, or {@code null} if the input was {@code null}
121	     */
122	    public static String normalizeEmail(String email) {
123	        return email == null ? null : email.toLowerCase();
124	    }
125	
126	    /**
127	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
128	     * truth for how a telephone is compared and persisted, so inputs that differ only in
129	     * formatting (spaces, dashes, brackets) are treated as the same number.
130	     *
131	     * <p>The rules are:
132	     * <ul>
133	     *   <li>spaces, dashes and brackets are stripped;</li>
134	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
135	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
136	     *       is dropped from the national digits;</li>
137	     *   <li>the result must have 8 to 15 digits after the {@code '+'}.</li>
138	     * </ul>
139	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
140	     * values are returned unchanged.
141	     *
142	     * @param telephone the raw telephone, possibly {@code null}
143	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
144	     *     valid E.164 number
145	     */
146	    public static String normalizeTelephone(String telephone) {
147	        if (telephone == null) {
148	            return null;
149	        }
150	        String trimmed = telephone.trim();
